  "view_hash": "37b2e9704de51f0fb47eefa278009343985f9e33c8d1fefb11e8c6871d96d4f3",
  "fim_base": {
    "estado": "exato",
    "valor": 10,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
